/**
 * A round mark identifying a person or workspace (`design/components/avatar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  avatarTone,
  cell,
  derived,
  initialsOf,
  useMember,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export type AvatarSize = NonNullable<AvatarProps['size']>

/** A round mark identifying a person or workspace: the inputs it takes, by the React member's prop names. */
export interface AvatarProps {
  /**
   * Set only when the avatar stands alone; beside a visible name it would repeat the name, so it
   * is `aria-hidden` instead.
   */
  label?: string
  /**
   * Initials come from this. "Ada Lovelace" → AL; one word → its first two.
   */
  name: string
  size?: 'sm' | 'md' | 'lg'
  src?: string
}

/** A round mark identifying a person or workspace. */
@Component({
  selector: 'pm-avatar',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `<span
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-fallback]="e3()"
[attr.data-tone]="e4()"
[attr.role]="e5()"
[attr.aria-label]="e6()"
[attr.aria-hidden]="e7()"
data-member="avatar"
>@if (e8()) {<!-- image -->
<img
[attr.class]="e9()"
[attr.src]="e10()"
[attr.alt]="e11()"
draggable="false"
(error)="h1()"
/>}
@if (e12()) {<pm-icon
name="user"
[size]="e13()"
></pm-icon>} @else {<!-- initials -->
<span
[attr.class]="e14()"
>{{ e15() }}</span>}</span>`,
})
export class Avatar {
  /**
   * Set only when the avatar stands alone; beside a visible name it would repeat the name, so it
   * is `aria-hidden` instead.
   */
  readonly label = input<AvatarProps['label']>(undefined)
  /**
   * Initials come from this. "Ada Lovelace" → AL; one word → its first two.
   */
  readonly name = input.required<AvatarProps['name']>()
  readonly size = input<Exclude<AvatarProps['size'], undefined>, AvatarProps['size']>('md', {
    transform: (value: AvatarProps['size']) => (value === undefined ? 'md' : value),
  })
  readonly src = input<AvatarProps['src']>(undefined)
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      name: () => this.name(),
      size: () => this.size(),
      src: () => this.src(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly failed = cell(() => '')
  protected readonly initials = derived(() => initialsOf(this.$p.name))
  protected readonly showImage = derived(
    () => this.$p.src !== undefined && this.failed.value !== this.$p.src,
  )
  protected readonly fallback = derived(() => (this.initials.value === '' ? 'icon' : 'initials'))
  protected readonly named = derived(() => this.$p.label !== undefined)

  protected e1() {
    return styles.avatar
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.showImage.value ? undefined : this.fallback.value
  }

  protected e4() {
    return this.fallback.value === 'initials' && !this.showImage.value
      ? avatarTone(this.$p.name)
      : undefined
  }

  protected e5() {
    return this.named.value ? 'img' : undefined
  }

  protected e6() {
    return this.$p.label
  }

  protected e7() {
    return !this.named.value ? true : undefined
  }

  protected e8() {
    return this.showImage.value
  }

  protected e9() {
    if (!this.showImage.value) return undefined as never
    return styles.image
  }

  protected e10() {
    if (!this.showImage.value) return undefined as never
    return this.$p.src
  }

  protected e11() {
    if (!this.showImage.value) return undefined as never
    return ''
  }

  protected h1(): void {
    if (!this.showImage.value) return
    this.failed.value = this.$p.src ?? ''
  }

  protected e12() {
    return this.fallback.value === 'icon'
  }

  protected e13(): IconProps['size'] {
    if (!(this.fallback.value === 'icon')) return undefined as never
    return this.$p.size
  }

  protected e14() {
    if (this.fallback.value === 'icon') return undefined as never
    return styles.initials
  }

  protected e15() {
    if (this.fallback.value === 'icon') return undefined as never
    return this.initials.value
  }
}
